import { describe, expect, test } from "bun:test";
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

/**
 * Migration journal consistency: every journal entry must have its SQL
 * file (and vice versa), tags must be sequential, and the newest
 * migration must be the one this test was written for - so a future
 * migration generated by hand (or a journal edited without its SQL)
 * fails loudly here instead of at deploy time.
 */
const DRIZZLE_DIR = join(import.meta.dir, "..", "drizzle");

interface JournalEntry {
  idx: number;
  tag: string;
}

describe("drizzle migration journal", () => {
  const journal = JSON.parse(
    readFileSync(join(DRIZZLE_DIR, "meta", "_journal.json"), "utf8"),
  ) as { entries: JournalEntry[] };
  const sqlFiles = readdirSync(DRIZZLE_DIR)
    .filter((f) => f.endsWith(".sql") && f !== "stamp-baseline.sql")
    .sort();

  test("journal entries and SQL files match 1:1, in order", () => {
    expect(journal.entries.map((e) => e.tag)).toEqual(
      sqlFiles.map((f) => f.replace(/\.sql$/, "")),
    );
    journal.entries.forEach((entry, i) => expect(entry.idx).toBe(i));
  });

  test("every journal entry has a snapshot file", () => {
    for (const entry of journal.entries) {
      const snapshot = join(
        DRIZZLE_DIR, "meta",
        `${String(entry.idx).padStart(4, "0")}_snapshot.json`,
      );
      expect(() => readFileSync(snapshot, "utf8")).not.toThrow();
    }
  });

  test("the newest migration (0019) adds messages.reply_to_external_id", () => {
    const newest = sqlFiles[sqlFiles.length - 1]!;
    expect(newest.startsWith("0019_")).toBe(true);
    const sql = readFileSync(join(DRIZZLE_DIR, newest), "utf8");
    expect(sql).toContain('ALTER TABLE "messages" ADD COLUMN "reply_to_external_id" text');
  });
});
